const graph = { 0: [1], 1: [2], 2: [], 3: [4], 4: [] };
function markReachable(node, reachable) {
  if (reachable.has(node)) return;
  reachable.add(node);
  for (const neighbor of graph[node]) {
    markReachable(neighbor, reachable);
  }
}

const reachable = new Set();
markReachable(0, reachable);

const allAddresses = [0, 1, 2, 3, 4];
const kept = allAddresses.filter((addr) => reachable.has(addr));
const collected = allAddresses.filter((addr) => !reachable.has(addr));

console.log('保留：', kept);
console.log('回收：', collected);

